	/* unwrap__5CZKitFii 0x2a5a00 (no source owner yet; written inline here): index wrapped into
	 * [0, count); -1 when index equals count or there are no items */
	int unwrap(int index, int count)
	{
		if (index == count || count == 0)
			return -1;

		while (index >= count)
			index -= count;

		while (index < 0)
			index += count;

		return index;
	}

